variables.ui:
[[[
const E = variables.entities;
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = k => states[E[k]];
const n = k => { const s = state(k)?.state; return s !== undefined && !['unknown','unavailable',''].includes(s) && Number.isFinite(Number(s)) ? Number(s) : null; };
const num = (k, unit='') => n(k) === null ? '<span class="missing">Unavailable</span>' : esc(new Intl.NumberFormat(hass.locale?.language || 'en', {maximumFractionDigits:1}).format(n(k))) + (unit ? '<span class="unit"> '+esc(unit)+'</span>' : '');
const icon = (name,cls='') => '<ha-icon class="'+cls+'" icon="mdi:'+name+'" aria-hidden="true"></ha-icon>';
const title = (i,t) => '<h2>'+icon(i)+'<span>'+esc(t)+'</span></h2>';
const pill = (text,tone='neutral') => '<span class="pill '+tone+'">'+esc(text)+'</span>';
const flag = k => n(k) === 1 ? pill('On','on') : n(k) === 0 ? pill('Off','off') : pill('Unknown','unknown');
const row = (i,label,value) => '<div class="data-row">'+icon(i)+'<span class="row-label">'+esc(label)+'</span><span class="row-value">'+value+'</span></div>';
const panel = (i,t,body,cls='') => '<section class="panel '+cls+'">'+title(i,t)+body+'</section>';
const burnerNames = {0:'Self check',1:'Standby',2:'Waiting for limit',3:'Prepurge',4:'Ignition',5:'Low fire hold',6:'Calibration',7:'Rate limit',8:'Modulating',9:'Postpurge',10:'Pump purge',11:'Standby delay',12:'Lockout',13:'Switch off',14:'Warm weather shutdown'};
const demandNames = {0:'Unknown',1:'Standby',2:'CH1',3:'CH2',4:'Domestic hot water',5:'Sequencer',6:'CH frost protection',7:'DHW frost protection',8:'Switch off',9:'Warm weather shutdown'};
const consumer = (key,fallback) => String(hass.entities?.[E[key]]?.name || state(key)?.attributes?.consumer_name || fallback);
const ch1 = consumer('ch1_heat_demand','Central heat 1');
const ch2 = consumer('ch2_heat_demand','Central heat 2');
const dhw = consumer('dhw_heat_demand','Domestic hot water');
const code = n('burner_control_state');
const burner = code === null ? 'Unknown' : (burnerNames[code] || 'Code '+code);
const burnerTone = code === null ? 'unknown' : code === 12 ? 'danger' : code === 8 ? 'on' : 'neutral';
const burnerPill = '<span title="ALTA manual HR 13; raw code '+esc(code ?? 'unavailable')+'">'+pill(burner,burnerTone)+'</span>';
const sourceCode = n('demand_source');
const source = sourceCode === 2 ? ch1 : sourceCode === 3 ? ch2 : sourceCode === 4 ? dhw : sourceCode === null ? 'Unknown' : (demandNames[sourceCode] || 'Code '+sourceCode);
const hold = n('hold_code'), lock = n('lockout_code');
const codesKnown = hold !== null && lock !== null;
const clear = codesKnown && hold === 0 && lock === 0;
const core = ['supply_temperature','return_temperature','burner_control_state','hold_code','lockout_code'];
const available = core.filter(k=>n(k)!==null).length;
const connection = available===core.length ? 'Online' : available ? 'Partial data' : 'Offline';
const tempUnit = state('supply_temperature')?.attributes?.unit_of_measurement || '°F';
const retUnit = state('return_temperature')?.attributes?.unit_of_measurement || '°F';
const metric = (i,label,value) => '<div class="metric"><div class="metric-label">'+icon(i)+'<span>'+esc(label)+'</span></div><strong>'+value+'</strong></div>';
const temp = k => n(k)===null ? '—' : num(k).replace(/<[^>]*>/g,'')+'<span>'+esc(state(k)?.attributes?.unit_of_measurement || '°F')+'</span>';
const delta = n('supply_temperature')!==null && n('return_temperature')!==null && tempUnit===retUnit ? esc(new Intl.NumberFormat(hass.locale?.language || 'en',{maximumFractionDigits:1}).format(n('supply_temperature')-n('return_temperature')))+'<span>'+esc(tempUnit)+'</span>' : '—';
const overview = panel('gauge','Overview','<div class="metrics">'+metric('thermometer','Supply Temp',temp('supply_temperature'))+metric('thermometer','Return Temp',temp('return_temperature'))+metric('delta','Delta-T',delta)+metric('target','Target Temp',temp('target_temperature'))+'</div><div class="burner-banner">'+icon('fire','flame')+'<span>Burner State</span>'+burnerPill+'</div>');
const diagnosticNote = !codesKnown ? '<div class="notice unknown">'+icon('help-circle-outline')+'<div><strong>Diagnostics unavailable</strong><small>Missing readings are not normal values.</small></div></div>' : clear ? '<div class="notice on">'+icon('check-circle')+'<div><strong>No hold or lockout reported</strong><small>Both current codes are zero.</small></div></div>' : '<div class="notice danger">'+icon('alert-circle')+'<div><strong>Boiler code reported</strong><small>Check the boiler display and manual.</small></div></div>';
return {
 header:'<header class="page-header">'+icon('fire','brand-flame')+'<div><h1>Burnham ALTA Boiler</h1><p>Read-only monitoring</p></div><div class="connection" title="Availability of the main monitoring readings">'+pill(connection,available===core.length?'on':available?'unknown':'off')+'</div></header>',
 overview,
 status:panel('layers-outline','Status',row('fire','Burner State',burnerPill)+row('source-branch','Demand Source','<span title="ALTA manual HR 100; raw code '+esc(sourceCode ?? 'unavailable')+'">'+pill(source)+'</span>')+row('fire','Flame Signal',num('flame_signal','%'))+row('fan','Fan Speed',num('fan_speed_feedback','RPM'))+row('lock-outline','Lockout / Hold Status',!codesKnown ? '<span class="missing">Unknown</span>' : clear ? 'Codes clear' : '<span class="fault">Code present</span>')),
 pumps:panel('pump','Pumps',row('pump','System Pump',flag('pump_a_status'))+row('pump','Boiler Pump',flag('pump_b_status'))+row('pump','DHW Pump',flag('pump_c_status'))),
 demand:panel('waves','Demand',row('radiator',ch1,flag('ch1_heat_demand'))+row('radiator',ch2,flag('ch2_heat_demand'))+row('water-pump',dhw,flag('dhw_heat_demand'))),
 diagnostics:panel('alert-outline','Diagnostics / Alerts',row('tag-outline','Lockout Code',num('lockout_code'))+row('tag-outline','Hold Code',num('hold_code'))+diagnosticNote),
 lifetime:panel('chart-bar','Lifetime Stats',row('clock-outline','Burner Runtime',num('burner_run_time_hours','h'))+row('sync','Burner Cycles',num('burner_cycle_count'))+row('pump','System Pump Cycles',num('pump_a_cycles'))+row('pump','Boiler Pump Cycles',num('pump_b_cycles'))+row('pump','DHW Pump Cycles',num('pump_c_cycles'))),
 note:'<p class="footnote">State names follow the ALTA manual; raw codes remain available in the entity details. Consumer labels do not confirm zone wiring. Counter decoding is provisional. This dashboard is not a boiler safety control.</p>'
};
]]]

cards.extra_styles:
:host { --alta-cyan:#27b9ed; --alta-purple:#af78f3; --alta-text:#f2f4f8; --alta-muted:#c0c7d1; }
#container { display:grid; grid-template-columns:repeat(12,minmax(0,1fr)); grid-template-areas:"header header header header header header header header header header header header" "overview overview overview overview overview overview overview status status status status status" "pumps pumps pumps pumps demand demand demand demand diagnostics diagnostics diagnostics diagnostics" "lifetime lifetime lifetime lifetime trend trend trend trend trend trend trend trend" "note note note note note note note note note note note note"; grid-template-rows:72px 270px 208px 278px auto; gap:14px; width:100%; max-width:1600px; margin:0 auto; }
#container > div { min-width:0; width:100%; height:100%; text-align:left; white-space:normal; overflow:visible; }
* { box-sizing:border-box; }
ha-icon { --mdc-icon-size:25px; width:25px; height:25px; flex-shrink:0; margin:0!important; color:#edf1f6; }
.panel { height:100%; padding:15px 17px; border:1px solid #4c5665; border-radius:16px; background:linear-gradient(130deg,#252c36 0%,#191f27 100%); box-shadow:0 5px 14px #00000025; color:var(--alta-text); overflow:hidden; }
h2 { display:flex; gap:12px; align-items:center; margin:0 0 8px; padding:0 0 11px; border-bottom:1px solid #444d5b; font-size:21px; line-height:1.15; font-weight:700; letter-spacing:-.25px; }
.data-row { display:flex; gap:11px; align-items:center; min-height:39px; border-bottom:1px solid #3b4451; font-size:15px; line-height:1.25; }
.data-row:last-child { border:0; }
.row-label { flex:1; min-width:0; overflow-wrap:anywhere; }
.row-value { flex:0 1 auto; max-width:60%; margin-left:auto; min-width:0; text-align:right; font-weight:650; font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
.pill { display:inline-flex; align-items:center; justify-content:center; padding:4px 11px; border-radius:12px; background:linear-gradient(#4b545f,#353d48); color:#f7f8fa; font-size:14px; font-weight:550; line-height:1.2; max-width:100%; white-space:normal; text-align:center; }
.pill.on { background:linear-gradient(#36733d,#24592e); box-shadow:inset 0 1px 0 #6b9b6550; }
.pill.off { background:linear-gradient(#4b535e,#343b45); color:#e2e6ed; }
.pill.unknown { background:#5a4729; color:#ffe6b3; }
.pill.danger { background:#873e3e; }
.unit { font-size:.92em; }
.missing { font-size:13px; color:#e3c995; }
.fault { color:#ffb2ac; }
.page-header { display:flex; align-items:center; gap:14px; height:100%; padding:0 4px; }
.page-header .brand-flame { width:45px; height:50px; --mdc-icon-size:50px; color:var(--alta-cyan); }
.page-header h1 { margin:0 0 4px; font-size:32px; font-weight:750; letter-spacing:-.6px; line-height:1.1; color:var(--alta-text); }
.page-header p { margin:0; font-size:16px; color:var(--alta-muted); }
.connection { margin-left:auto; flex-shrink:0; }
.connection .pill { padding:9px 13px; border:1px solid #4f7756; background:#19271f; font-size:14px; gap:7px; }
.connection .pill::before { content:""; width:9px; height:9px; border-radius:50%; background:#5bca62; }
.connection .pill.unknown::before { background:#e5ba68; }
.connection .pill.off::before { background:#aaa; }
.metrics { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); margin:20px 0 22px; }
.metric { padding:0 14px; border-right:1px solid #47515f; text-align:center; min-width:0; }
.metric:first-child { padding-left:0; }
.metric:last-child { padding-right:0; border:0; }
.metric-label { display:flex; align-items:center; justify-content:center; gap:8px; font-size:14px; white-space:normal; line-height:1.3; margin-bottom:10px; }
.metric strong { font-size:32px; letter-spacing:-.8px; font-weight:750; font-variant-numeric:tabular-nums; line-height:1; }
.metric strong span { font-size:.76em; letter-spacing:-.4px; }
.burner-banner { display:flex; align-items:center; gap:15px; min-height:60px; border:1px solid #465161; border-radius:12px; padding:9px 15px; background:linear-gradient(110deg,#29323e,#242b35); font-size:19px; font-weight:550; }
.burner-banner .flame { color:var(--alta-cyan); --mdc-icon-size:37px; width:37px; height:37px; }
.burner-banner > span:last-child { margin-left:auto; }
.burner-banner .pill { font-size:18px; padding:6px 14px; }
.notice { display:flex; align-items:center; gap:10px; padding:9px 10px; margin-top:6px; border-radius:11px; line-height:1.15; }
.notice strong { display:block; font-size:14px; }
.notice small { display:block; margin-top:5px; font-size:12px; color:#e2e8e3; }
.notice.on { background:#213f2b; border:1px solid #356342; }
.notice.on ha-icon { color:#61d05d; }
.notice.unknown { background:#443924; border:1px solid #75603a; }
.notice.danger { background:#542d30; border:1px solid #8f5054; }
.footnote { color:#a9b4c3; font-size:11px; line-height:1.5; margin:0 4px; max-width:110ch; }
@media(max-width:1050px) {
 #container { grid-template-columns:repeat(6,minmax(0,1fr))!important; grid-template-areas:"header header header header header header" "overview overview overview overview overview overview" "status status status status status status" "pumps pumps pumps demand demand demand" "diagnostics diagnostics diagnostics lifetime lifetime lifetime" "trend trend trend trend trend trend" "note note note note note note"!important; grid-template-rows:72px 270px auto 208px auto 278px auto!important; }
   .panel { min-height:208px; } #status .data-row { min-height:38px; }
}
@media(max-width:600px) {
 #container { display:flex!important; flex-direction:column; gap:12px; }
 #container > div { height:auto!important; } .page-header { min-height:72px; gap:9px; } .page-header h1 { font-size:23px; } .page-header p { font-size:13px; } .page-header .brand-flame { width:32px; --mdc-icon-size:36px; }
 .connection .pill { padding:7px 9px; font-size:12px; } .connection .pill::before { width:7px;height:7px; }
 .panel { padding:14px; min-height:0; } h2 { font-size:20px; } .metrics { grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px 0; margin:20px 0; } .metric:nth-child(2) { border:0; padding-right:0; } .metric:nth-child(3) { padding-left:0; } .metric strong { font-size:32px; } .metric-label { font-size:14px; }
 .burner-banner { font-size:17px; gap:8px; } .burner-banner .pill { font-size:15px; } .data-row { min-height:43px; font-size:15px; }    .footnote { font-size:11px; }
}
@media(prefers-reduced-motion:reduce) { * { animation:none!important; transition:none!important; } }
